-- data/actor_profiles.lua: one ActorProfile per actor archetype, merging:
--   repo actor_ai.lua `profiles` (package ids, action kind/code, movement/projectile flags) [repo; values match ROM below]
--   sprite_type      : actor +0x0E (SpriteType; 3/5/11/14 names from repo) [C values / H names]
--   weapon           : stable item ID -> data/weapons.lua record (corp guard = max_power) [C]
--   reinforcement    : building spawn profile +0x10 used by the alarm spawner 0x1E04A (doc 20a §10) - per-building,
--                      so it lives on the building/run record, not here [C].
-- Generated by an inline script from the repo + rom.bin; regenerate rather than hand-edit.
local E = require("enums")
local SpriteType = E.SpriteType

---@class ActorProfile
local ActorProfile = {}
ActorProfile.__index = ActorProfile
setmetatable(ActorProfile, { __call = function(_, t) return setmetatable(t, ActorProfile) end })
function ActorProfile:weapon_record() return self.weapon and require("data.weapons").get(self.weapon) or nil end
function ActorProfile:is_armed() return self.weapon ~= nil end

local M = { ActorProfile = ActorProfile, by_id = {
    ["corp_guard_k05_item06"] = ActorProfile{ id = "corp_guard_k05_item06", package_id = "corp_security.max_power_heavy_pistol", sprite_type = SpriteType.CORP_GUARD, action_kind = "item", weapon = "max_power", controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["pedestrian_k0b_none00"] = ActorProfile{ id = "pedestrian_k0b_none00", package_id = "pedestrian.no_active_action", sprite_type = SpriteType.PEDESTRIAN, action_kind = "none", weapon = nil, controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["field_runner_k03_none00"] = ActorProfile{ id = "field_runner_k03_none00", package_id = "runner.field_controlled", sprite_type = SpriteType.FIELD_RUNNER, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = false },
    ["hell_hound_k0c_none00"] = ActorProfile{ id = "hell_hound_k0c_none00", package_id = "creature.hell_hound.source_target_motion", sprite_type = SpriteType.HELL_HOUND, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["gargoyle_k0d_none00"] = ActorProfile{ id = "gargoyle_k0d_none00", package_id = "creature.gargoyle.source_target_motion", sprite_type = SpriteType.GARGOYLE, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["wendigo_k0e_none00"] = ActorProfile{ id = "wendigo_k0e_none00", package_id = "creature.wendigo.source_target_motion", sprite_type = SpriteType.WENDIGO, action_kind = "none", weapon = nil, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["weapon_projectile"] = ActorProfile{ id = "weapon_projectile", package_id = "combat.weapon_projectile", sprite_type = nil, action_kind = "none", weapon = nil, controls_movement = false, projectile = true, dynamic_encounter_only = false },
    ["field_hit_spark"] = ActorProfile{ id = "field_hit_spark", package_id = "combat.player_hit_spark", sprite_type = SpriteType.HIT_SPARK, action_kind = "none", weapon = nil, controls_movement = false, projectile = false, dynamic_encounter_only = false },
} }
-- Dynamic profiles receive a semantic action identity from the host adapter.
function M.dynamic(sprite_type, action_kind, action_id)
    local identity = action_id or "none"
    return ActorProfile{ id = "dynamic." .. tostring(sprite_type) .. "." .. action_kind .. "." .. identity,
        sprite_type = sprite_type, action_kind = action_kind, action_id = action_id,
        weapon = action_kind == "item" and action_id or nil,
        controls_movement = sprite_type ~= SpriteType.THON,
        projectile = false, dynamic_encounter_only = true }
end
return M
